import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CQxpk36T.js";const k=JSON.parse('{"title":"Hosting on a server","description":"","frontmatter":{},"headers":[],"relativePath":"en/hebergement.md","filePath":"en/hebergement.md","lastUpdated":1793574169000}'),n={name:"en/hebergement.md"};function o(h,e,l,r,p,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="hosting-on-a-server" tabindex="-1">Hosting on a server <a class="header-anchor" href="#hosting-on-a-server" aria-label="Permalink to &quot;Hosting on a server&quot;">​</a></h1><p><code>npm run dev</code> is enough to describe your property. To have it on your phone every day, HAven builds into a few static files, served by a small web server on a machine at home (the Home Assistant server, a NAS, a mini PC).</p><h2 id="with-docker" tabindex="-1">With Docker <a class="header-anchor" href="#with-docker" aria-label="Permalink to &quot;With Docker&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><ol><li>Builds the app into <code>dist/</code>, with the property chosen in <code>.env.local</code>;</li><li>starts the <code>maison-3d</code> container (<code>deploy/docker-compose.yml</code>): a <a href="https://caddyserver.com" target="_blank" rel="noreferrer">Caddy</a> serving <code>dist/</code> on <strong><code>127.0.0.1:8099</code></strong>.</li></ol><p>After each change to the property (or after dropping in a <code>retouches.json</code>), run <code>npm run deploy</code> again. The container restarts by itself with the machine.</p><div class="info custom-block"><p class="custom-block-title">Why 127.0.0.1</p><p>The container only listens on the machine itself: nothing is exposed on the network until you decide so. Tailscale (below) publishes it on your private network.</p></div><p>Caddy is set up so updates show at once: versioned files (<code>/assets/…</code>) are kept a year by the browser, the page and the offline cache are always revalidated.</p><h2 id="without-docker" tabindex="-1">Without Docker <a class="header-anchor" href="#without-docker" aria-label="Permalink to &quot;Without Docker&quot;">​</a></h2><p><code>dist/</code> is a static site: any web server works (nginx, Apache, Home Assistant&#39;s <code>www</code> folder…). It just needs to return <code>index.html</code> for unknown addresses.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # then serve dist/</span></span></code></pre></div><h2 id="from-your-phone-with-tailscale" tabindex="-1">From your phone, with Tailscale <a class="header-anchor" href="#from-your-phone-with-tailscale" aria-label="Permalink to &quot;From your phone, with Tailscale&quot;">​</a></h2><p>To reach it from anywhere without opening anything on the internet, the simplest is <a href="https://tailscale.com" target="_blank" rel="noreferrer">Tailscale</a>, a private network between your devices:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http=80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8099</span></span></code></pre></div><p>Then <code>http://&lt;machine name&gt;</code> on the phone, with Tailscale on. On iPhone: Share → &quot;Add to Home Screen&quot; installs it full screen.</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>For <strong>instant offline opening</strong> (the app cache), browsers require HTTPS. With Tailscale: enable &quot;HTTPS Certificates&quot; in the Tailscale console (DNS section), then:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --http=80</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tailscale</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bg</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --https=443</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8099</span></span></code></pre></div><p>The address becomes <code>https://&lt;machine name&gt;.&lt;your tailnet&gt;.ts.net</code>.</p><div class="warning custom-block"><p class="custom-block-title">Home Assistant too</p><p>An HTTPS page can&#39;t talk to an HTTP Home Assistant. Serve Home Assistant over HTTPS the same way (<code>tailscale serve</code> on port 8123, for example), and use that address in HAven&#39;s settings. See <a href="/HAven-docs/en/home-assistant/#http-or-https">Connecting</a>.</p></div><h2 id="a-wall-tablet" tabindex="-1">A wall tablet <a class="header-anchor" href="#a-wall-tablet" aria-label="Permalink to &quot;A wall tablet&quot;">​</a></h2><ul><li>Install HAven on the home screen for full screen;</li><li>connect it with a dedicated Home Assistant account;</li><li>choose the <strong>Économe</strong> (saver) graphics quality if the tablet runs hot;</li><li>the interface darkens by itself at night.</li></ul><h2 id="updating-haven" tabindex="-1">Updating HAven <a class="header-anchor" href="#updating-haven" aria-label="Permalink to &quot;Updating HAven&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Your property folder isn&#39;t touched: it is outside git.</p>`,25)])])}const g=s(n,[["render",o]]);export{k as __pageData,g as default};
